package com.axiom.application.testreport; import com.axiom.domain.test.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class TestStabilityService {public Result classify(List<TestStatus> statuses,int failToPass,int sameFingerprintFailures){int total=statuses.size(),fails=(int)statuses.stream().filter(s->s==TestStatus.FAILED||s==TestStatus.ERROR).count(),passes=(int)statuses.stream().filter(s->s==TestStatus.PASSED).count();TestStabilityClass c;if(total<5)c=TestStabilityClass.INSUFFICIENT_HISTORY;else if(failToPass>=2)c=TestStabilityClass.FLAKY;else if(failToPass==1)c=TestStabilityClass.SUSPECTED_FLAKY;else if(fails>=4&&fails/(double)total>=.8&&sameFingerprintFailures>=4)c=TestStabilityClass.CONSISTENTLY_FAILING;else if(total>=20&&fails==0)c=TestStabilityClass.STABLE;else if(fails==0)c=TestStabilityClass.LIKELY_STABLE;else c=TestStabilityClass.INSUFFICIENT_HISTORY;return new Result(c,"stability-v1",total,passes,fails,failToPass,List.of(c==TestStabilityClass.FLAKY?"MULTIPLE_FAIL_TO_PASS_TRANSITIONS":c==TestStabilityClass.SUSPECTED_FLAKY?"UNCHANGED_RERUN_FAIL_TO_PASS":c==TestStabilityClass.CONSISTENTLY_FAILING?"REPEATED_SAME_FAILURE":"EXECUTION_HISTORY"));}public record Result(TestStabilityClass classification,String version,int total,int passed,int failed,int failToPass,List<String> evidence){}}
